package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

//truebdd:concept given "installation"
func conceptbef0930c9a09dec2b565c664833e27eb5e85810f2e50d51372923cf970aa997c(state *State, args []string) error {
	program, err := filepath.Abs(filepath.Join("..", "..", "tmp", "calc-program", "calc"))
	if err != nil {
		return fmt.Errorf("resolve calculator program path: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(program), 0o755); err != nil {
		return fmt.Errorf("create calculator program directory: %w", err)
	}
	command := exec.Command("go", "build", "-o", program, "./services/calc")
	command.Dir = "../.."
	output, err := command.CombinedOutput()
	if err != nil {
		return fmt.Errorf("build calculator: %w: %s", err, output)
	}
	state.Program = program
	return nil
}

package steps

import (
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

func Register(suite Registrar) {
	suite.Step(`^the Owner doubles (-?\d+)$`, doubling)
	suite.Step(`^the result is (-?\d+)$`, result)

	suite.Step("^the calculator (?:is|has been) installed$", conceptbef0930c9a09dec2b565c664833e27eb5e85810f2e50d51372923cf970aa997c)
}

//truebdd:concept when "doubling"
func doubling(state *State, args []string) error {
	if state.Program == "" {
		return fmt.Errorf("the calculator is not installed")
	}
	command := exec.Command(state.Program, "double", args[0])
	command.Dir = "../.."
	output, err := command.CombinedOutput()
	if err != nil {
		return fmt.Errorf("calculator double: %w: %s", err, output)
	}
	state.Value, err = strconv.Atoi(strings.TrimSpace(string(output)))
	return err
}

//truebdd:concept then "result"
func result(state *State, args []string) error {
	want, err := strconv.Atoi(args[0])
	if err != nil {
		return err
	}
	if state.Value != want {
		return fmt.Errorf("expected %d, got %d", want, state.Value)
	}
	return nil
}
